// Draws the card and the bar's small symbols. Symbols are drawn, never emoji.
import {t} from './i18n.js';
import {siblingsOf,orderLabel} from './birth-order.js';
import {AXES} from './sim.js';
import {personaName,setPersonaName,amuletOf,AMULET_COLOR,holdingsOfLife,balanceOf,natureOf,assetsOf,sellAsset} from './life-persona.js';
import {PURCHASES,buy} from './finance.js';
const NS='http://www.w3.org/2000/svg',money=n=>'฿'+Math.round(n).toLocaleString('en');
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const PATHS={amulet:'M8 1v3M4 8a4 4 0 1 0 8 0 4 4 0 1 0-8 0',cross:'M8 1v14M3.5 5.5h9',owned:'M2 8l6-5 6 5M4 7v7h8V7M7 14v-4h2v4',rented:'M2 8l6-5 6 5M4 7v7h8V7',family:'M2 8l6-5 6 5M4 7v7h8V7M6 14v-3M10 14v-3',none:'M2 13h12M4 13V9l9-3',car:'M2 11V8l2-3h7l3 3v3H2M5 13a1.2 1.2 0 1 0 .01 0M11 13a1.2 1.2 0 1 0 .01 0',gold:'M3 3c0 7 10 7 10 0M8 8.2v2M6.5 12a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0',watch:'M5 5h6v6H5zM6 5V1h4v4M6 11v4h4v-4',land:'M1 13h14M3 13l3-5 3 3 2-2 3 4',house:'M2 8l6-5 6 5M4 7v7h8V7M7 14v-4h2v4',motorbike:'M4 12a2 2 0 1 0 .01 0M12 12a2 2 0 1 0 .01 0M4 12l3-5h3l2 5M9 7l1-2h2'};
function glyph(kind,color,label){const s=document.createElementNS(NS,'svg');s.setAttribute('viewBox','0 0 16 16');s.setAttribute('class','slot-glyph');s.setAttribute('role','img');s.setAttribute('aria-label',label);const p=document.createElementNS(NS,'path');p.setAttribute('d',PATHS[kind]);p.setAttribute('fill','none');p.setAttribute('stroke',color||'currentColor');p.setAttribute('stroke-width','1.5');s.append(p);const tt=document.createElementNS(NS,'title');tt.textContent=label;s.append(tt);return s;}
function pie(share,size,label){const s=document.createElementNS(NS,'svg');s.setAttribute('viewBox','0 0 36 36');s.setAttribute('width',size);s.setAttribute('height',size);s.setAttribute('class','slot-pie');s.setAttribute('role','img');s.setAttribute('aria-label',label);const ring=(color,dash)=>{const c=document.createElementNS(NS,'circle');c.setAttribute('cx',18);c.setAttribute('cy',18);c.setAttribute('r',15.9);c.setAttribute('fill','none');c.setAttribute('stroke',color);c.setAttribute('stroke-width','6');if(dash!==undefined){c.setAttribute('stroke-dasharray',dash+' 100');c.setAttribute('transform','rotate(-90 18 18)');}return c;};s.append(ring('currentColor'));if(share>0)s.append(ring('#f59e0b',Math.round(share*100)));return s;}
const HOME={owned:'House: yours',rented:'Rented home',family:'Your family’s home',none:'No home'};
export function renderSlots(root,s){const a=amuletOf(s),h=holdingsOfLife(s),b=balanceOf(s);root.replaceChildren(glyph(a.cross?'cross':'amulet',AMULET_COLOR[a.tier],t(a.label)),glyph(h.home,undefined,t(HOME[h.home])),...assetsOf(s).filter(x=>x.key!=='amulet'&&x.key!=='house').map(x=>glyph(x.key,x.key==='gold'?'#d9a92e':undefined,t(x.label)+' '+money(x.value))),pie(b.share,14,t('Owed against what you own: {n}%').replace('{n}',Math.round(b.share*100))));}
export function renderPersona(pane,s,apply){
 let card=pane.querySelector('.persona');if(!card){card=el('section','persona');pane.prepend(card);}
 const a=amuletOf(s),h=holdingsOfLife(s),b=balanceOf(s),n=natureOf(s),head=el('div','persona-head'),who=el('div'),input=el('input','persona-name');input.value=personaName(s);input.maxLength=24;input.setAttribute('aria-label',t('Your name'));input.onchange=()=>apply(setPersonaName(s,input.value));
 {const [k,n1,k1]=orderLabel(siblingsOf(s)),bo=t(k).replace('{n}',n1).replace('{k}',k1);who.append(input,el('p','persona-meta',t('Age {n}').replace('{n}',s.age)+' · '+bo+' · '+t(n.body)+' · '+t(n.drive)));}const worth=el('div','persona-worth');worth.append(el('b',undefined,money(b.worth)),el('span',undefined,t('Net worth')));head.append(who,worth);
 const stats=el('dl','persona-stats'),stat=(k,v)=>stats.append(el('dt',undefined,k),el('dd',undefined,String(Math.round(v))));stat(t('Health'),s.health);stat(t('Wellbeing'),s.wellbeing);for(const x of AXES)stat(t(x.key==='iq'?'IQ':x.key==='eq'?'EQ':x.label),s.skills?.[x.key]??0);
 const gear=el('ul','persona-gear');
 const line=pts=>{const svg=document.createElementNS(NS,'svg'),lo=Math.min(...pts),hi=Math.max(...pts),p=document.createElementNS(NS,'polyline');svg.setAttribute('viewBox','0 0 40 14');svg.setAttribute('class','asset-spark');svg.setAttribute('aria-hidden','true');p.setAttribute('points',pts.map((v,i)=>(i/Math.max(1,pts.length-1)*38+1).toFixed(1)+','+(13-(hi===lo?.5:(v-lo)/(hi-lo))*12).toFixed(1)).join(' '));p.setAttribute('fill','none');p.setAttribute('stroke','currentColor');p.setAttribute('stroke-width','1.3');svg.append(p);return svg;};
 for(const it of assetsOf(s)){const li=el('li'),sell=el('button','asset-sell',t('Sell'));sell.type='button';sell.disabled=!s.finance||s.age<15||s.stage!=='review';sell.onclick=()=>apply(sellAsset(s,it.key));li.append(glyph(it.key==='amulet'?(a.cross?'cross':'amulet'):it.key,it.key==='amulet'?AMULET_COLOR[a.tier]:it.key==='gold'?'#d9a92e':undefined,''),el('span','asset-name',t(it.label)),line(it.points),el('b','asset-value',money(it.value)),sell);gear.append(li);}
 const homeLi=el('li');if(h.home!=='owned'){homeLi.append(glyph(h.home,undefined,''),el('span','asset-name',t(HOME[h.home])));gear.append(homeLi);}
 const shop=el('div','persona-shop');if(s.finance&&s.age>=20&&s.stage==='review'){const spend=s.finance.available+s.finance.reserve;for(const[key,item]of Object.entries(PURCHASES)){if(!item.minAge||s.finance.purchases.some(p=>p.key===key))continue;const b=el('button','shop-card');b.type='button';b.append(glyph(key,undefined,''),el('span',undefined,t(item.label)),el('small',undefined,money(item.cost)));b.disabled=spend<item.cost||!!s.story?.pending;b.onclick=()=>apply(buy(s,key));shop.append(b);}}
 const owed=el('div','persona-owed');owed.append(pie(b.share,44,t('Owed against what you own: {n}%').replace('{n}',Math.round(b.share*100))),el('p',undefined,t('Cash {c} · Funds {f} · House {h} · Gold {g}').replace('{c}',money(b.cash)).replace('{f}',money(b.invest)).replace('{h}',money(b.house)).replace('{g}',money(b.gold))+' − '+t('Debts {d} · Mortgage {m}').replace('{d}',money(b.debt)).replace('{m}',money(b.mortgage))));
 card.replaceChildren(head,stats,gear,owed,...(shop.children.length?[shop]:[]));
}
